from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for n in [4,6,8,21]:
 print(f'PAGE {n}')
 p=r.pages[n-1]
 out=[]
 def visit(text,cm,tm,font,size):
  if text.strip():
   x=cm[0]*tm[4]+cm[2]*tm[5]+cm[4]
   y=cm[1]*tm[4]+cm[3]*tm[5]+cm[5]
   if n==21: out.append((round(y,1),round(x,1),text.strip()))
 if n==21:
  p.extract_text(visitor_text=visit)
  for v in out: print(v)
print('XM average-to-average percentage increases:', [(a/b-1)*100 for a,b in zip([4.35,2.94,2.97],[2.98,1.77,1.78])])
